  assert.deepStrictEqual(parse(''), []);
  assert.deepStrictEqual(parse('a,b\r\nc,d\ne,f\rg,h\n'), [['a', 'b'], ['c', 'd'], ['e', 'f'], ['g', 'h']]);
  assert.deepStrictEqual(parse('﻿a,b'), [['a', 'b']]);
  assert.deepStrictEqual(parse('a,\n,'), [['a', ''], ['', '']]);
  assert.deepStrictEqual(parse(' a , b'), [[' a ', ' b']]);
  assert.deepStrictEqual(parse('a"b,c'), [['a"b', 'c']]);
  assert.throws(() => parse(1), TypeError);
  assert.throws(() => parse('a', { delimiter: '"' }), TypeError);
  assert.throws(() => parse('a', { delimiter: ',,' }), TypeError);
});

test('quotes and empty lines', () => {
  assert.deepStrictEqual(parse('"a,\n""b""",c'), [['a,\n"b"', 'c']]);
  assert.deepStrictEqual(parse('a\n\nb\n\n'), [['a'], [''], ['b'], ['']]);
  assert.deepStrictEqual(parse('a\n\nb\n\n', { skipEmptyLines: true }), [['a'], ['b']]);
  assert.deepStrictEqual(parse('""\n'), [['']]);
  assert.deepStrictEqual(parse('a;b', { delimiter: ';' }), [['a', 'b']]);
});

test('errors', () => {
  const e = (t, o) => { try { parse(t, o); } catch (x) { return x; } };
  let x = e('a\r\nb,"c\n');
  assert.ok(x instanceof CsvError && x instanceof Error);
  assert.deepStrictEqual([x.line, x.column], [2, 3]);
  x = e('a\n"b"c');
  assert.deepStrictEqual([x.line, x.column], [2, 4]);
  x = e('a,b,a', { header: true });
  assert.deepStrictEqual([x.line, x.column], [1, 5]);
  x = e('a,b\n1,2\n3', { header: true });
  assert.deepStrictEqual([x.line, x.column], [3, 1]);
});

test('header', () => {
  assert.deepStrictEqual(parse('a,b\n1,2', { header: true }), [{ a: '1', b: '2' }]);
  assert.deepStrictEqual(parse('a,b\n', { header: true }), []);
});

test('stringify', () => {
  assert.strictEqual(stringify([]), '');
  assert.strictEqual(stringify([['a', 1, true, null, undefined]], { eol: '\n' }), 'a,1,true,,\n');
  assert.strictEqual(stringify([['a,b', 'c"d', ' e', 'f ']]), '"a,b","c""d"," e","f "\r\n');
  assert.strictEqual(stringify([['']]), '""\r\n');
  assert.strictEqual(stringify([{ b: 2 }], { header: ['a', 'b'] }), 'a,b\r\n,2\r\n');
  assert.throws(() => stringify([[{}]]), TypeError);
  assert.throws(() => stringify([], { eol: '\r' }), TypeError);
});

test('round trip', () => {
  const rows = [[''], ['a', ''], ['﻿x'], [' '], ['"'], ['a\r\nb', ',', '\r'], ['', '']];
  for (const o of [{}, { skipEmptyLines: true }, { delimiter: ';', eol: '\n' }]) {
    assert.deepStrictEqual(parse(stringify(rows, o), o), rows);
  }
});

test('trim option', () => {
  assert.deepStrictEqual(parse(' a \t, b ', { trim: true }), [['a', 'b']]);
  assert.deepStrictEqual(parse(' a ', {}), [[' a ']]);
  assert.deepStrictEqual(parse(' "  a "" " \t,\t"b"  \n', { trim: true }), [['  a " ', 'b']]);
  assert.deepStrictEqual(parse('  \n', { trim: true }), [['']]);
  assert.deepStrictEqual(parse(' a \t b\t', { trim: true, delimiter: '\t' }), [['a', 'b']]);
  assert.throws(() => parse('"a" x', { trim: true }), CsvError);
  assert.throws(() => parse('"a" x'), CsvError);
});

test('comment option', () => {
  assert.deepStrictEqual(parse('#c\na,b\r\n#d\r\nc#,d\n#e', { comment: '#' }), [['a', 'b'], ['c#', 'd']]);
  assert.deepStrictEqual(parse('#a\nb', {}), [['#a'], ['b']]);
  assert.deepStrictEqual(parse('a\n\n#x\n', { comment: '#', skipEmptyLines: false }), [['a'], ['']]);
  assert.deepStrictEqual(parse(' #a', { comment: '#' }), [[' #a']]);
  for (const c of [',', '"', '\r', '\n', '', '##', 1]) {
    assert.throws(() => parse('a', { comment: c }), TypeError);
  }
  assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
  try { parse('#x\n#y\n"a', { comment: '#' }); assert.fail(); } catch (x) { assert.strictEqual(x.line, 3); }
});
